mapper.select:
SELECT id, event_id, trace_id, request_time, method, uri, route, query_string,
       client_ip, user_agent, referer, http_status, success, cost_ms,
       exception_type, created_at
FROM api_access_log
WHERE request_time >= #{from}
  AND request_time < #{to}
  AND (request_time > #{cursorTime}
       OR (request_time = #{cursorTime} AND id > #{cursorId}))
ORDER BY request_time ASC, id ASC
LIMIT #{limit}

